<template><VCard title="Expediente KYB"><VCardText v-if="item"><p><strong>Empresa:</strong> {{ item.legal_name }}</p><p><strong>Estado:</strong> {{ statusLabel(item.workflow_status) }} / {{ statusLabel(item.kyb_status) }}</p><p><strong>Identificacion:</strong> {{ item.tax_id_masked }}</p><p><strong>Pais:</strong> {{ item.country_name ?? item.country_id }}</p><p><strong>Propietario:</strong> {{ item.owner?.display_name ?? item.owner?.username }}</p><p><strong>Representante:</strong> {{ item.representative?.display_name ?? item.representative?.username ?? item.representative_user_id }}</p><VTable density="compact"><tbody><tr v-for="owner in item.beneficial_owners" :key="owner.id"><td>{{ owner.full_name }}</td><td>{{ owner.ownership_percentage ?? 0 }}%</td><td>{{ owner.is_controller ? "Controlador" : "Beneficiario" }}</td></tr></tbody></VTable><VBtn v-for="document in item.documents" :key="document.public_reference ?? document.download_endpoint" class="mr-2" variant="outlined" @click="api.downloadDocument(document)">{{ document.document_type }} · {{ statusLabel(document.status) }}</VBtn></VCardText></VCard></template><script setup lang="ts">import { statusLabel } from "@/utils/statusLabels"; import { useCompaniesApi } from "@/services/companiesApi"; import { onMounted, ref } from "vue"; import { useRoute } from "vue-router"; const item = ref<any>(null); const route = useRoute(); const api = useCompaniesApi(); onMounted(async () => { item.value = await api.adminShow(Number(route.params.id)); });</script>
